 "content": "def transform(grid):
    # Recolor full rows and columns of the line/frame color (the minority color) to 2.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    line_color = min(counts, key=counts.get)
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if all(v == line_color for v in grid[r])}
    cols = {c for c in range(w) if all(grid[r][c] == line_color for r in range(h))}
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w): out[r][c] = 2
    for c in cols:
        for r in range(h): out[r][c] = 2
    return out
